<?php
declare(strict_types=1);namespace App\Controllers;use App\Exceptions\NotFoundException;use App\Support\{Request,Response};
final class AdminInvestmentController extends Controller {public function index(Request $r):Response{$rows=app('database')?->select('SELECT i.*,u.email FROM investment_positions i JOIN users u ON u.id=i.user_id ORDER BY i.purchased_at DESC LIMIT 100')??[];return $this->view('admin/investments',['title'=>'Investments','investments'=>$rows],'layouts.admin');}public function sales(Request $r):Response{$rows=app('database')?->select('SELECT s.*,u.email,i.company_name_snapshot FROM sale_requests s JOIN users u ON u.id=s.user_id JOIN investment_positions i ON i.id=s.investment_id ORDER BY s.requested_at DESC LIMIT 100')??[];return $this->view('admin/sales',['title'=>'Sale requests','sales'=>$rows],'layouts.admin');}public function saleAction(Request $r):Response{try{$id=(int)$r->route('sale');if($r->input('action')==='approve')app('investments')->approveSale($id,(int)$_SESSION['user_id'],$r->input('price')!==''?(int)$r->input('price'):null);else app('investments')->rejectSale($id,(int)$_SESSION['user_id'],(string)$r->input('reason'));$this->flash('success','Sale request updated.');}catch(\Throwable $e){$this->flash('error',$e->getMessage());}return $this->redirect('admin.sales');}}
